const assert = require('node:assert/strict');
const Module = require('node:module');
const originalLoad = Module._load;
const slots = [];
let cursor = 0;
let cleanup;
Module._load = function (name, ...args) {
  if (name === 'react') return {
    useRef(value) { const i = cursor++; return slots[i] ?? (slots[i] = { current: value }); },
    useReducer() { cursor++; return [0, () => {}]; },
    useEffect(effect) { cursor++; if ("'!cleanup) cleanup = effect(); },
  };
  return originalLoad.call(this, name, ...args);
};
const { usePreparation } = require('"'/workspace/src/usePreparation.js');
const requests = [];
const retries = new Map();
let next = 0;
const cancelled = [];
globalThis.__preparationTransport = token => new Promise(resolve => requests.push({ token, resolve }));
globalThis.__schedulePreparationRetry = callback => { const id = ++next; retries.set(id, callback); return id; };
globalThis.__cancelPreparationRetry = id => { cancelled.push(id); retries.delete(id); };
function render() { cursor = 0; return usePreparation('file'); }
function fire(id) { const callback = retries.get(id); retries.delete(id); callback(); }
(async () => {
  let hook = render();
  hook.start();
  assert.equal(requests.length, 1);
  requests[0].resolve(false);
  await Promise.resolve();
  assert.equal(hook.snapshot().retryScheduled, true);
  fire(1);
  assert.equal(requests.length, 2);
  requests[1].resolve(true);
  await Promise.resolve();
  assert.deepEqual(hook.snapshot().completed, ['file']);
  assert.equal(hook.snapshot().loading, false);
  hook.reopen('file');
  requests[2].resolve(false);
  await Promise.resolve();
  hook.close();
  assert.ok(cancelled.includes(2));
  hook.reopen('file');
  requests[3].resolve(true);
  await Promise.resolve();
  assert.deepEqual(hook.snapshot().completed, ['file']);
  hook.reopen('other');
  hook.close();
  requests[4].resolve(true);
  await Promise.resolve();
  assert.deepEqual(hook.snapshot().completed, ['file']);
  cleanup();
  console.log('polling, ready completion, cancellation, and stale response checks passed');
})().catch(error => { console.error(error); process.exitCode = 1; });
